"""Safe online solver for the interactive maze challenge.

The solver keeps an internal coordinate, senses only the current cell, and never
chooses a move that would make a cell's visit count exceed two.  It prioritizes
unknown/unvisited neighbours that move toward the exit, and uses bounded
backtracking only when necessary.
"""
from __future__ import annotations

from collections import defaultdict, deque
from dataclasses import dataclass, field
import argparse
import json
import sys
import time
from typing import Dict, Iterable, List, Optional, Protocol, Tuple
from urllib import request

# Directions: 0=up, 1=down, 2=left, 3=right
DIRS: Dict[int, Tuple[int, int]] = {
    0: (0, 1),
    1: (0, -1),
    2: (-1, 0),
    3: (1, 0),
}
OPPOSITE = {0: 1, 1: 0, 2: 3, 3: 2}
DIR_NAMES = {0: "up", 1: "down", 2: "left", 3: "right"}
Coord = Tuple[int, int]


class MazeClient(Protocol):
    def maze_size(self) -> int: ...
    def sense(self) -> List[int]: ...
    def move(self, direction: int) -> dict: ...
    def finish(self) -> dict: ...


class HttpMazeClient:
    def __init__(self, base_url: str, timeout: float = 5.0):
        self.base_url = base_url.rstrip("/")
        self.timeout = timeout

    def _json(self, method: str, path: str, payload: Optional[dict] = None) -> dict:
        data = None
        headers = {}
        if payload is not None:
            data = json.dumps(payload).encode("utf-8")
            headers["Content-Type"] = "application/json"
        req = request.Request(self.base_url + path, data=data, headers=headers, method=method)
        with request.urlopen(req, timeout=self.timeout) as resp:
            return json.loads(resp.read().decode("utf-8"))

    def maze_size(self) -> int:
        return int(self._json("GET", "/maze_size")["maze_size"])

    def sense(self) -> List[int]:
        return list(self._json("GET", "/sense")["connectivity"])

    def move(self, direction: int) -> dict:
        return self._json("POST", "/move", {"direction": direction})

    def finish(self) -> dict:
        return self._json("POST", "/finish", {})


@dataclass
class OnlineMazeSolver:
    client: MazeClient
    verbose: bool = True
    n: int = 0
    pos: Coord = (1, 1)
    visits: Dict[Coord, int] = field(default_factory=lambda: defaultdict(int))
    known: Dict[Coord, List[int]] = field(default_factory=dict)
    stack: List[Coord] = field(default_factory=list)
    moves_made: int = 0

    def log(self, msg: str) -> None:
        if self.verbose:
            print(msg, flush=True)

    def in_bounds(self, p: Coord) -> bool:
        x, y = p
        return 1 <= x <= self.n and 1 <= y <= self.n

    def neighbor(self, p: Coord, direction: int) -> Coord:
        dx, dy = DIRS[direction]
        return (p[0] + dx, p[1] + dy)

    def open_neighbors(self, p: Coord) -> Iterable[Tuple[int, Coord]]:
        conn = self.known[p]
        for d, open_ in enumerate(conn):
            if open_:
                q = self.neighbor(p, d)
                if self.in_bounds(q):
                    yield d, q

    def unblocked_candidate_dirs(self, conn: List[int]) -> List[Tuple[int, Coord]]:
        out: List[Tuple[int, Coord]] = []
        for d, open_ in enumerate(conn):
            if not open_:
                continue
            q = self.neighbor(self.pos, d)
            if self.in_bounds(q) and self.visits[q] < 2:
                out.append((d, q))
        return out

    def score_forward(self, q: Coord) -> Tuple[int, int, int, int]:
        """Lower score is better for exploration toward the top-right exit."""
        x, y = q
        dist = (self.n - x) + (self.n - y)
        # Strongly prefer unvisited cells, then progress to exit, then right/up bias.
        return (self.visits[q], dist, -x, -y)

    def direction_to(self, a: Coord, b: Coord) -> int:
        delta = (b[0] - a[0], b[1] - a[1])
        for d, step in DIRS.items():
            if step == delta:
                return d
        raise ValueError(f"{a} and {b} are not adjacent")

    def choose_next(self, conn: List[int]) -> Optional[Tuple[int, Coord]]:
        candidates = self.unblocked_candidate_dirs(conn)
        if not candidates:
            return None

        # 1) Prefer completely unvisited neighbours; this avoids loops and makes progress.
        unvisited = [(d, q) for d, q in candidates if self.visits[q] == 0]
        if unvisited:
            return min(unvisited, key=lambda item: self.score_forward(item[1]))

        # 2) If no unvisited neighbour exists, backtrack along the DFS stack if possible.
        if self.stack:
            parent = self.stack[-1]
            for d, q in candidates:
                if q == parent:
                    return d, q

        # 3) Last resort: choose the least-visited move that still trends toward the exit.
        return min(candidates, key=lambda item: self.score_forward(item[1]))

    def apply_stack_update(self, old: Coord, new: Coord) -> None:
        if self.stack and self.stack[-1] == new:
            self.stack.pop()
        else:
            self.stack.append(old)

    def run(self, max_steps: Optional[int] = None) -> dict:
        self.n = self.client.maze_size()
        if max_steps is None:
            max_steps = 4 * self.n * self.n
        self.pos = (1, 1)
        self.visits[self.pos] += 1
        self.log(f"maze_size={self.n}, start={self.pos}, exit={(self.n, self.n)}")

        while self.moves_made <= max_steps:
            if self.pos == (self.n, self.n):
                self.log(f"at exit {self.pos}; calling finish")
                result = self.client.finish()
                self.log(f"finish -> {result}")
                return result

            conn = self.client.sense()
            if conn == [0, 0, 0, 0]:
                raise RuntimeError("sense returned all walls/game-over signal before reaching exit")
            self.known[self.pos] = conn
            choice = self.choose_next(conn)
            if choice is None:
                raise RuntimeError(f"No legal move from {self.pos}; visits={dict(self.visits)} conn={conn}")
            direction, nxt = choice
            if self.visits[nxt] >= 2:
                raise AssertionError(f"Refusing third visit to {nxt}")
            self.log(
                f"step={self.moves_made:03d} pos={self.pos} conn={conn} "
                f"move={DIR_NAMES[direction]}->{nxt} next_visits={self.visits[nxt] + 1}"
            )
            resp = self.client.move(direction)
            if resp.get("status") != "moved":
                raise RuntimeError(f"Move {direction} from {self.pos} to {nxt} failed: {resp}")
            old = self.pos
            self.pos = nxt
            self.visits[self.pos] += 1
            if self.visits[self.pos] > 2:
                raise AssertionError(f"Visited {self.pos} more than twice")
            self.apply_stack_update(old, self.pos)
            self.moves_made += 1

        raise RuntimeError(f"Exceeded max_steps={max_steps}; pos={self.pos}; visits={dict(self.visits)}")


class SimMazeClient:
    """Small deterministic simulator used by tests."""
    def __init__(self, n: int, edges: Iterable[Tuple[Coord, Coord]]):
        self.n = n
        self.pos = (1, 1)
        self.adj: Dict[Coord, set[Coord]] = defaultdict(set)
        self.visit_counts: Dict[Coord, int] = defaultdict(int)
        self.visit_counts[self.pos] = 1
        self.finished = False
        for a, b in edges:
            self.adj[a].add(b)
            self.adj[b].add(a)

    def maze_size(self) -> int:
        return self.n

    def sense(self) -> List[int]:
        conn = []
        for d in range(4):
            conn.append(1 if self._neighbor(self.pos, d) in self.adj[self.pos] else 0)
        return conn

    def _neighbor(self, p: Coord, d: int) -> Coord:
        dx, dy = DIRS[d]
        return (p[0] + dx, p[1] + dy)

    def move(self, direction: int) -> dict:
        q = self._neighbor(self.pos, direction)
        if q not in self.adj[self.pos]:
            return {"status": "illegal"}
        self.pos = q
        self.visit_counts[q] += 1
        if self.visit_counts[q] > 2:
            return {"status": "illegal", "message": "overvisit"}
        return {"status": "moved"}

    def finish(self) -> dict:
        self.finished = True
        if self.pos == (self.n, self.n):
            return {"status": "Congratulations, destination reached"}
        return {"status": "illegal", "message": "Not at destination, game over"}


def main(argv: Optional[List[str]] = None) -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--url", default="http://maze:8088")
    parser.add_argument("--quiet", action="store_true")
    parser.add_argument("--max-steps", type=int, default=None)
    args = parser.parse_args(argv)
    solver = OnlineMazeSolver(HttpMazeClient(args.url), verbose=not args.quiet)
    result = solver.run(max_steps=args.max_steps)
    ok = result.get("status") == "Congratulations, destination reached"
    return 0 if ok else 2


if __name__ == "__main__":
    raise SystemExit(main())
